import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AlertController, LoadingController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { VEHICLE_CATALOG, VehicleCatalogEntry } from './vehicle-profile.catalog';
import { PROFILE_FIELDS, PROFILE_SECTIONS } from './vehicle-profile.fields';
import { VERIFIED_VEHICLE_PRESETS } from './vehicle-profile.presets';
import { VehicleProfile, VehicleProfileStore } from './vehicle-profile.store';

@Component({
  selector: 'app-vehicle-profile',
  templateUrl: './vehicle-profile.component.html',
  styleUrls: ['./vehicle-profile.component.scss']
})
export class VehicleProfileComponent implements OnInit {
  readonly sections = PROFILE_SECTIONS;
  readonly verifiedPresets = VERIFIED_VEHICLE_PRESETS;
  readonly catalog = [...VERIFIED_VEHICLE_PRESETS, ...VEHICLE_CATALOG];
  readonly catalogCount = this.catalog.length;
  readonly fieldCount = PROFILE_FIELDS.length;
  isShow = false;
  isCheck = true;
  form: FormGroup;
  profiles: VehicleProfile[] = [];
  currentId = '';
  catalogQuery = '';
  suggestions: VehicleCatalogEntry[] = [];
  matches = 0;
  message = '';
  source = '';
  dirty = false;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private alerts: AlertController,
    public loadingController: LoadingController,
    private courseService: CourseService,
    private siteService: SliderService
  ) {}

  ngOnInit(): void {
    const controls: Record<string, any> = {
      name: ['', Validators.required], make: [''], model: [''], trim: [''], year: ['']
    };
    PROFILE_FIELDS.forEach(field => controls[field.key] = [null,
      field.kind === 'number' ? [Validators.min(field.min), Validators.max(field.max)] : []]);
    this.form = this.fb.group(controls);
    this.refreshProfiles();
    const active = VehicleProfileStore.active();
    if (active) { this.editProfile(active); }
    this.form.valueChanges.subscribe(() => this.dirty = true);
    void this.check();
  }

  ionViewWillEnter(): void {
    this.refreshProfiles();
    const active = VehicleProfileStore.active();
    if (this.form && !this.dirty && active && active.id !== this.currentId) {
      this.editProfile(active);
    }
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(49).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;
                              this.isShow = true;
                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
              this.isShow = true;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  get filledCount(): number {
    return PROFILE_FIELDS.filter(field => this.form && this.form.get(field.key)?.value !== null &&
      this.form.get(field.key)?.value !== '').length;
  }

  onCatalogSearch(event: Event): void {
    this.catalogQuery = (event.target as HTMLInputElement).value.trim();
    const query = this.searchKey(this.catalogQuery);
    if (query.length < 2) { this.suggestions = []; this.matches = 0; return; }
    const matching = this.catalog.filter(entry =>
      this.searchKey(`${entry.make} ${entry.model} ${entry.trim || ''}`).includes(query));
    this.matches = matching.length;
    this.suggestions = matching.slice(0, 40);
  }

  async usePreset(entry: VehicleCatalogEntry): Promise<void> {
    if (!await this.confirmDiscard()) { return; }
    this.clearForm();
    const title = [entry.make, entry.model, entry.trim].filter(Boolean).join(' ');
    this.form.patchValue({ ...entry.values, name: title, make: entry.make,
      model: entry.model, trim: entry.trim || '' });
    this.source = entry.source || '';
    this.catalogQuery = '';
    this.suggestions = [];
    this.matches = 0;
    this.message = entry.source ? 'تیپ مستند انتخاب شد. سال، قطعات و مقادیر واقعی پروژه خودت را بررسی کن.' :
      'مدل انتخاب شد. تیپ، سال و مشخصات فنی خودرویت را تکمیل کن.';
  }

  private searchKey(value: string): string {
    return value.toLocaleLowerCase().replace(/[۰-۹]/g, digit => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(digit)))
      .replace(/[٠-٩]/g, digit => String('٠١٢٣٤٥٦٧٨٩'.indexOf(digit)))
      .replace(/ي/g, 'ی').replace(/ك/g, 'ک').replace(/[\u200c\s_-]+/g, '');
  }

  async newProfile(): Promise<void> {
    if (!await this.confirmDiscard()) { return; }
    this.clearForm();
  }

  private clearForm(): void {
    this.currentId = '';
    this.source = '';
    this.form.reset();
    this.dirty = false;
    this.message = 'پروفایل تازه آماده است.';
  }

  editProfile(profile: VehicleProfile): void {
    this.currentId = profile.id;
    this.source = profile.source || '';
    this.form.reset({ ...profile.values, name: profile.name, make: profile.make,
      model: profile.model, trim: profile.trim, year: profile.year });
    this.dirty = false;
    this.message = '';
  }

  async selectProfile(profile: VehicleProfile): Promise<void> {
    if (!await this.confirmDiscard()) { return; }
    VehicleProfileStore.select(profile.id);
    this.refreshProfiles();
    this.editProfile(profile);
    this.message = 'این خودرو اکنون پروفایل فعال ابزارهای تیونر پلاس است.';
  }

  saveProfile(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      this.message = 'نام پروژه و مقادیر عددی را بررسی کنید.';
      return;
    }
    const raw = this.form.getRawValue();
    const values: VehicleProfile['values'] = {};
    PROFILE_FIELDS.forEach(field => {
      const value = raw[field.key];
      values[field.key] = value === '' || value === null || value === undefined ? null :
        field.kind === 'number' ? Number(value) : String(value).trim();
    });
    const profile: VehicleProfile = {
      id: this.currentId || VehicleProfileStore.createId(),
      name: String(raw.name || '').trim(), make: String(raw.make || '').trim(),
      model: String(raw.model || '').trim(), trim: String(raw.trim || '').trim(),
      year: String(raw.year || '').trim(), values, source: this.source,
      updatedAt: new Date().toISOString()
    };
    if (!profile.name) { this.message = 'نام پروژه لازم است.'; return; }
    try {
      VehicleProfileStore.save(profile);
      this.currentId = profile.id;
      this.refreshProfiles();
      this.dirty = false;
      this.message = 'پروفایل ذخیره و برای ابزارهای دیگر فعال شد.';
    } catch { this.message = 'ذخیره در مرورگر انجام نشد. فضای ذخیره‌سازی یا تنظیمات حریم خصوصی را بررسی کنید.'; }
  }

  private async confirmDiscard(): Promise<boolean> {
    if (!this.dirty) { return true; }
    const alert = await this.alerts.create({
      cssClass: 'tuner-plus-beta-alert',
      header: 'تغییرات ذخیره نشده', message: 'تغییرات فعلی کنار گذاشته شود؟',
      buttons: [{ text: 'بازگشت', role: 'cancel' }, { text: 'کنار گذاشتن', role: 'confirm' }]
    });
    await alert.present();
    const result = await alert.onDidDismiss();
    return result.role === 'confirm';
  }

  exportProfiles(): void {
    if (!this.profiles.length) { return; }
    const blob = new Blob([VehicleProfileStore.exportJson()], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'tuner-plus-vehicle-profiles.json';
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  async importProfiles(event: Event): Promise<void> {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) { return; }
    if (!await this.confirmDiscard()) { input.value = ''; return; }
    try {
      if (file.size > 1000000) { throw new Error('File too large'); }
      const count = VehicleProfileStore.importJson(await file.text());
      this.refreshProfiles();
      const active = VehicleProfileStore.active();
      if (active) { this.editProfile(active); }
      this.message = `${count} پروفایل وارد شد.`;
    } catch { this.message = 'فایل پشتیبان معتبر نیست یا ذخیره مرورگر در دسترس نیست.'; }
    input.value = '';
  }

  async deleteProfile(profile: VehicleProfile): Promise<void> {
    const alert = await this.alerts.create({
      cssClass: 'tuner-plus-beta-alert',
      header: 'حذف پروفایل', message: `«${profile.name}» حذف شود؟`,
      buttons: [{ text: 'انصراف', role: 'cancel' }, { text: 'حذف', role: 'destructive', handler: () => {
        try {
          VehicleProfileStore.remove(profile.id);
          this.refreshProfiles();
          if (this.currentId === profile.id) {
            const active = VehicleProfileStore.active();
            if (active) { this.editProfile(active); } else { this.clearForm(); }
          }
          this.message = 'پروفایل حذف شد.';
        } catch { this.message = 'حذف پروفایل انجام نشد.'; }
      } }]
    });
    await alert.present();
  }

  private refreshProfiles(): void { this.profiles = VehicleProfileStore.list(); }
}
