export interface ProfileField {
  key: string;
  label: string;
  unit?: string;
  min?: number;
  max?: number;
  step?: number;
  kind?: 'text' | 'number';
  hint?: string;
}

export interface ProfileSection { title: string; description: string; fields: ProfileField[]; }

const n = (key: string, label: string, unit = '', min?: number, max?: number, step = 1): ProfileField =>
  ({ key, label, unit, min, max, step, kind: 'number' });
const t = (key: string, label: string): ProfileField => ({ key, label, kind: 'text' });

